window.YunchengV3={stageAt,cents,validate,migrate,archivedAt,setPeriod:value=>{period=value;offset=0},getPeriodOffset:()=>offset};
try{const res=await fetch('/api/workspace');if(!res.ok)throw Error('本地数据库服务尚未连接');const r=await res.json();revision=r.revision;const original=JSON.stringify(r.data);data=migrate(r.data||data);if(original!==JSON.stringify(data))await persist();savedData=jsonCopy(data);ready=true;render()}catch(err){$('#app').innerHTML=`<main class="startup-error"><h1>暂时无法打开工作空间</h1><p>${esc(err.message)}</p><p>请启动本地服务，然后刷新。原浏览器数据不会被清除。</p><button onclick="location.reload()">重新连接</button></main>`}
